add_task(async function testMessageSecurityShortcut() {
  // Add an S/MIME message to the inbox folder.
  const smimeFile = new FileUtils.File(
    getTestFilePath("../smime/data/alice.env.eml")
  );

  // Add the fetched S/MIME message to the inbox folder.
  const copyListener = new PromiseTestUtils.PromiseCopyListener();
  MailServices.copy.copyFileMessage(
    smimeFile,
    gInbox,
    null,
    false,
    0,
    "",
    copyListener,
    null
  );
  await copyListener.promise;

  // Select the first row, which should contain the S/MIME message.
  await select_click_row(-1);

  const aboutMessage = get_about_message();
  Assert.equal(
    aboutMessage.document
      .getElementById("encryptionTechBtn")
      .querySelector("span").textContent,
    "S/MIME",
    "should indicate S/MIME encrypted"
  );

  const popupshown = BrowserTestUtils.waitForEvent(
    aboutMessage.document.getElementById("messageSecurityPanel"),
    "popupshown"
  );

  // Hit Ctrl+Alt+S / Cmd+Control+S to open the Security Info panel.
  const modifiers =
    AppConstants.platform == "macosx"
      ? { accelKey: true, ctrlKey: true }
      : { accelKey: true, altKey: true };
  EventUtils.synthesizeKey("s", modifiers, aboutMessage);

  // The Message Security popup panel should show up.
  await popupshown;

  // The message was encrypted to Bob, whose certificate and key we have,
  // so the panel must show Bob as the recipient.
  Assert.ok(
    !aboutMessage.document.getElementById("encryptionCert").collapsed,
    "the encryption certificate section should be shown"
  );
  Assert.equal(
    aboutMessage.document.getElementById("encryptedFor").textContent,
    "Bob",
    "should show the name of the recipient certificate"
  );
  Assert.equal(
    aboutMessage.document.getElementById("recipientEmail").textContent,
    "bob@example.com",
    "should show the email address of the recipient certificate"
  );

  // Select the row again since the focus moved to the popup panel.
  await select_click_row(-1);
  // Delete the message.
  await press_delete();
